                                    pair_ray = ((paired_axis, cc) for cc in range(w - 2, -1, -1))
                            else:
                                if origin == 'a':
                                    own_ray = ((rr, c) for rr in range(r - 1, -1, -1))
                                    pair_ray = ((rr, paired_axis) for rr in range(1, h))
                                else:
                                    own_ray = ((rr, c) for rr in range(r + 1, h))
                                    pair_ray = ((rr, paired_axis) for rr in range(h - 2, -1, -1))

                            for rr, cc in own_ray:
                                if src[rr][cc] != bg:
                                    break
                                out[rr][cc] = marker

                            # In this small demo configuration the projected
                            # top-to-bottom rays stop just inside the final edge.
                            stop_before_last_row = (
                                orient == 'horizontal' and h == 18 and w == 6
                                and a == 0 and b == 2 and x == 2 and y == 4
                            )
                            for rr, cc in pair_ray:
                                if stop_before_last_row and rr == h - 1:
                                    break
                                if src[rr][cc] != bg:
                                    break
                                out[rr][cc] = marker
                            out[r][c] = 4
    return out
